/* global self, caches, Response, URL, __VERSION__, __SHELL_PAGES__, __ASSETS__ -- lint only; build-pwa.ts drops this line */
/* TimeSpot service worker — generated by scripts/build-pwa.ts; don't edit dist/sw.js.
 *
 * Pages: network first, revalidated past any HTTP cache (`no-cache`), so
 * an online visitor always gets the current deploy whatever headers the
 * host sends; a copy is kept for offline. Offline, a page falls back to its cached copy, then to the app
 * shell ("/"), which renders whatever route the URL names.
 * Everything else under /_expo and /assets is content-hashed: cache first.
 */
const VERSION = __VERSION__
const SHELL_PAGES = __SHELL_PAGES__
const ASSETS = __ASSETS__
const CACHE = `timespot-${VERSION}`

// A redirected response can't answer a navigation; store a plain copy.
async function clean(response) {
  if (!response.redirected) return response
  return new Response(await response.blob(), {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  })
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE)
      await cache.addAll(ASSETS)
      for (const page of SHELL_PAGES) {
        const response = await fetch(page, { cache: "no-cache" })
        if (!response.ok) throw new Error(`${page}: ${response.status}`)
        await cache.put(page, await clean(response))
      }
      await self.skipWaiting()
    })(),
  )
})

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) {
        if (key.startsWith("timespot-") && key !== CACHE) await caches.delete(key)
      }
      await self.clients.claim()
    })(),
  )
})

async function page(request) {
  const cache = await caches.open(CACHE)
  const url = new URL(request.url)
  const key = url.pathname.replace(/\.html$/, "").replace(/(.)\/$/, "$1")
  try {
    const response = await fetch(request, { cache: "no-cache" })
    if (response.ok) await cache.put(key, await clean(response.clone()))
    return response
  } catch (error) {
    const cached = (await cache.match(key)) ?? (await cache.match("/"))
    if (cached) return cached
    throw error
  }
}

async function asset(request) {
  const cache = await caches.open(CACHE)
  const cached = await cache.match(request)
  if (cached) return cached
  const response = await fetch(request)
  if (response.ok) await cache.put(request, response.clone())
  return response
}

self.addEventListener("fetch", (event) => {
  const { request } = event
  if (request.method !== "GET") return
  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return
  if (request.mode === "navigate") return event.respondWith(page(request))
  if (url.pathname.startsWith("/_expo/") || url.pathname.startsWith("/assets/")) {
    event.respondWith(asset(request))
  }
})
